type Phase = 'investigation' | 'containment' | 'won' | 'lost'
type Modal = 'briefing' | 'reveal' | 'diagnosis' | 'advance' | 'complete' | 'event' | 'wrong' | 'win' | 'lost' | 'feedback' | null
type MissionAct = 'proteger' | 'investigar' | 'decidir' | 'controlar' | 'resultado'
type PilotStage = 'called' | 'field' | 'map' | 'board' | 'tactical' | 'response' | 'diagnosis' | 'result'
type Student = { name: string; semester: string; focus: string }
type Reveal = Clue | Intervention
type Area = 'investigacao' | 'conduta' | 'controle' | 'tempo' | 'diagnostico'
type Log = { id: string; area: Area; title: string; note: string; tone: 'good' | 'warn' | 'neutral' }
type Player = { playerId: string; xp: number; coins: number; completed: number[]; dailyClaimed: string; lastActiveDay: string; streak: number; bestScore: number; inventory: string[]; equippedStyle: string }
type RewardSummary = { xp: number; coins: number; missionXP: number; dailyXP: number; speedXP: number; firstClear: boolean }
type Participant = { playerId: string; displayName: string; xp: number; bestScore: number; plays: number; completed: number; createdAt: string; lastPlayedAt: string | null; lastMissionId: number | null }
type Records = { summary: { players: number; active_players: number; plays: number; completed: number }; leaderboards: { score: RecordEntry[]; xp: RecordEntry[]; plays: RecordEntry[] }; participants: Participant[] }
type RecordEntry = { playerId: string; displayName: string; value: number }
type ActiveGame = { missionId: number; variantId?: string | null; cycle: number; actions: number; cases: number; care: number; resources: number; clueIds: string[]; interventionIds: string[]; logs: Log[]; urgentCare: boolean; pendingLabId: string | null; phase: Extract<Phase, 'investigation' | 'containment'>; dailyMission: boolean; pilotStage?: PilotStage; insightEnergy?: number; hintUses?: string[]; tacticalChoiceId?: string | null }
type TacticalOption = { id: string; icon: string; title: string; text: string; consequence: string; factor: number; tone: 'good' | 'warn' | 'neutral'; tacticalChoiceId?: string }
type TacticalMoment = { title: string; text: string; objective: string; options: TacticalOption[] }
type OperationalVariant = { id: string; label: string; openingSyndrome: string; brief: string; initialData: { label: string; value: string }[]; call: string; fieldHint: string }

