const patientStories: Partial<Record<number, PatientStory>> = {
  1: { name: 'Farah, 24 anos', label: 'VOZ DO TERRITÓRIO', text: '“A água entrou em casa ontem. Hoje acordei muito fraca e minha irmã trouxe a gente até aqui. Vizinhos da mesma rua também começaram a passar mal.”', question: 'A história de Farah não fecha o diagnóstico, mas orienta a primeira pergunta: quem precisa de cuidado agora e qual exposição pode conectar as pessoas?', art: mahanPatientStory },
  2: { name: 'João, 19 anos', label: 'CHEGADA À TRIAGEM', text: '“A febre começou há três dias. Minha mãe ficou preocupada porque agora dói atrás dos olhos e eu não consigo comer direito. Na rua, mais gente está falando de febre.”', question: 'A história mostra uma pessoa, não a resposta. Procure primeiro sinais de alarme e depois o padrão que se repete no bairro.', art: alvoradaPatientStory },
  3: { name: 'Lina, 20 anos', label: 'REDE DE CONTATOS', text: '“Voltei do evento com tosse e febre. Dois colegas da mesma fileira também faltaram à aula, e hoje apareceram manchas.”', question: 'Uma história de contato ajuda a reconstruir a cronologia, mas é preciso cruzá-la com os achados clínicos e a vigilância.', art: campusPatientStory },
  4: { name: 'Marcos, 42 anos', label: 'HISTÓRIA DE CUIDADO', text: '“A tosse não passou. Eu pensei que fosse melhorar, mas perdi peso e agora outras pessoas do mesmo pavilhão comentam que estão assim.”', question: 'Quando a evolução é longa, o tempo e os ambientes compartilhados merecem uma lente de investigação própria.', art: pavilionPatientStory },
  5: { name: 'Nair, 67 anos', label: 'FLUXO DA UNIDADE', text: '“Minha família pergunta por que mudaram meu quarto. A equipe explica que está organizando as barreiras enquanto investiga um achado incomum.”', question: 'Em serviços de saúde, o caminho entre pessoas, objetos e ambientes pode ser tão importante quanto um sintoma isolado.', art: auroraPatientStory },
  6: { name: 'Amina, 31 anos', label: 'CHEGADA AO VALE', text: '“A febre vem e volta desde que passei alguns dias perto do rio. Hoje acordei com calafrio forte e meu irmão insistiu para eu procurar o posto.”', question: 'A cronologia e a exposição mudam as perguntas que a equipe deve fazer, mas o cuidado de gravidade não espera a confirmação.', art: safiraPatientStory },
  7: { name: 'Caio, 18 anos', label: 'ALERTA NO CAMPUS', text: '“A dor de cabeça ficou muito forte de repente. Meus colegas me trouxeram porque fiquei sensível à luz e não melhorava em casa.”', question: 'Algumas histórias exigem cuidado urgente enquanto a equipe identifica quem teve contato relevante e qual exame realmente ajuda.', art: pontePatientStory },
  8: { name: 'Rosa, 38 anos', label: 'HISTÓRIA DA ILHA', text: '“Depois da festa, várias pessoas da família ficaram mal. Eu ajudei a preparar comida e a água da comunidade ficou turva depois da chuva.”', question: 'A equipe precisa separar coincidência de elo comum: pessoas, alimento, água e tempo contam uma mesma história?', art: ilhaPatientStory },
}
